#include <stdio.h>
#include <string.h>

void computeCRC(char data[], char divisor[])
{
    char dividend[100], temp[100];
    int dataLen, divLen, i, j;

    strcpy(dividend, data);

    dataLen = strlen(data);
    divLen = strlen(divisor);

    /* Append zeros */
    for(i = 0; i < divLen - 1; i++)
        dividend[dataLen + i] = '0';

    dividend[dataLen + divLen - 1] = '\0';

    strcpy(temp, dividend);

    /* Modulo-2 division */
    for(i = 0; i <= strlen(temp) - divLen; i++)
    {
        if(temp[i] == '1')
        {
            for(j = 0; j < divLen; j++)
            {
                temp[i + j] =
                    (temp[i + j] == divisor[j]) ? '0' : '1';
            }
        }
    }

    printf("\nDataword      : %s", data);
    printf("\nGenerator     : %s", divisor);

    printf("\nCRC Remainder : ");
    for(i = strlen(temp) - (divLen - 1); i < strlen(temp); i++)
        printf("%c", temp[i]);

    printf("\nCodeword      : %s", data);

    for(i = strlen(temp) - (divLen - 1); i < strlen(temp); i++)
        printf("%c", temp[i]);

    printf("\n");
}

int main()
{
    char data[100];
    int choice;

    printf("Enter binary data: ");
    scanf("%s", data);

    printf("\nChoose CRC Polynomial");
    printf("\n1. CRC-12");
    printf("\n2. CRC-16");
    printf("\n3. CRC-CCITT");
    printf("\nEnter choice: ");
    scanf("%d", &choice);

    switch(choice)
    {
        case 1:
            computeCRC(data, "1100000001111");
            break;

        case 2:
            computeCRC(data, "11000000000000101");
            break;

        case 3:
            computeCRC(data, "10001000000100001");
            break;

        default:
            printf("Invalid choice!\n");
    }

    return 0;
}

#include <stdio.h>

int main() {
    int totalFrames, windowSize;
    int base = 0, i, end, lostFrame;

    printf("Enter the total number of frames: ");
    scanf("%d", &totalFrames);

    printf("Enter the window size: ");
    scanf("%d", &windowSize);

    while (base < totalFrames) {
        end = (base + windowSize < totalFrames) ? (base + windowSize) : totalFrames;

        printf("\nSending Frames: ");
        for (i = base; i < end; i++) {
            printf("%d ", i);
        }

        printf("\nEnter the lost frame number (-1 for no loss): ");
        scanf("%d", &lostFrame);

        if (lostFrame == -1 || lostFrame < base || lostFrame >= end) {
            printf("All frames acknowledged.\n");
            base = end;
        } else {
            printf("Frame %d lost.\n", lostFrame);
            printf("Go-Back-N: Retransmitting from Frame %d.\n", lostFrame);
            base = lostFrame;
        }
    }

    printf("\nAll frames transmitted successfully.\n");

    return 0;
}

#include <stdio.h>

#define MAX 10
#define INF 9999

int main() {
    int graph[MAX][MAX], distance[MAX], visited[MAX];
    int n, source, i, j, min, next;

    printf("Enter the number of vertices: ");
    scanf("%d", &n);

    printf("Enter the adjacency matrix:\n");
    for(i = 0; i < n; i++) {
        for(j = 0; j < n; j++) {
            scanf("%d", &graph[i][j]);

            // Replace 0 with INF (except diagonal)
            if(graph[i][j] == 0 && i != j)
                graph[i][j] = INF;
        }
    }

    printf("Enter the source vertex (0 to %d): ", n - 1);
    scanf("%d", &source);

    // Initialize distances and visited array
    for(i = 0; i < n; i++) {
        distance[i] = graph[source][i];
        visited[i] = 0;
    }

    distance[source] = 0;
    visited[source] = 1;

    // Dijkstra's Algorithm
    for(i = 1; i < n; i++) {
        min = INF;

        for(j = 0; j < n; j++) {
            if(!visited[j] && distance[j] < min) {
                min = distance[j];
                next = j;
            }
        }

        visited[next] = 1;

        for(j = 0; j < n; j++) {
            if(!visited[j] && (min + graph[next][j] < distance[j])) {
                distance[j] = min + graph[next][j];
            }
        }
    }

    // Display shortest distances
    printf("\nShortest distances from vertex %d:\n", source);
    for(i = 0; i < n; i++) {
        printf("To vertex %d = %d\n", i, distance[i]);
    }

    return 0;
}

#include <stdio.h>

#define MAX 20

int main()
{
    int n, i, j, source;
    int graph[MAX][MAX];
    int visited[MAX] = {0};
    int queue[MAX];
    int front = 0, rear = 0;

    printf("Enter number of hosts: ");
    scanf("%d", &n);

    printf("\nEnter the adjacency matrix:\n");
    printf("(Enter 1 if two hosts are connected, otherwise 0)\n");

    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            scanf("%d", &graph[i][j]);
        }
    }

    printf("\nEnter the source host (1-%d): ", n);
    scanf("%d", &source);

    source--;   // Convert to 0-based index

    /* Start BFS */
    visited[source] = 1;
    queue[rear++] = source;

    printf("\nBroadcast Tree:\n");
    printf("Parent -> Child\n");

    while (front < rear)
    {
        int current = queue[front++];

        for (i = 0; i < n; i++)
        {
            if (graph[current][i] == 1 && visited[i] == 0)
            {
                visited[i] = 1;
                queue[rear++] = i;

                printf("Host %d -> Host %d\n",
                       current + 1, i + 1);
            }
        }
    }

    return 0;
}

#include <stdio.h>

#define MAX 10
#define INF 999

int main()
{
    int n, i, j, k;
    int cost[MAX][MAX];
    int dist[MAX][MAX];
    int next[MAX][MAX];
    int changed;

    printf("Enter the number of nodes: ");
    scanf("%d", &n);

    printf("\nEnter the cost matrix:\n");
    printf("(Enter 999 for no direct connection)\n");

    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            scanf("%d", &cost[i][j]);

            dist[i][j] = cost[i][j];

            if (i == j)
                dist[i][j] = 0;

            next[i][j] = j;
        }
    }

    /* Distance Vector Algorithm */
    do
    {
        changed = 0;

        for (i = 0; i < n; i++)
        {
            for (j = 0; j < n; j++)
            {
                for (k = 0; k < n; k++)
                {
                    if (dist[i][k] != INF &&
                        dist[k][j] != INF &&
                        dist[i][j] > dist[i][k] + dist[k][j])
                    {
                        dist[i][j] = dist[i][k] + dist[k][j];
                        next[i][j] = next[i][k];
                        changed = 1;
                    }
                }
            }
        }

    } while (changed);

    /* Display routing tables */
    for (i = 0; i < n; i++)
    {
        printf("\nRouting Table for Node %d\n", i + 1);
        printf("---------------------------------\n");
        printf("Destination\tCost\tNext Hop\n");

        for (j = 0; j < n; j++)
        {
            printf("%d\t\t%d\t%d\n",
                   j + 1, dist[i][j], next[i][j] + 1);
        }
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

void encrypt(char text[], int key)
{
    int i;

    for (i = 0; text[i] != '\0'; i++)
    {
        if (text[i] >= 'A' && text[i] <= 'Z')
        {
            text[i] = (text[i] - 'A' + key) % 26 + 'A';
        }
        else if (text[i] >= 'a' && text[i] <= 'z')
        {
            text[i] = (text[i] - 'a' + key) % 26 + 'a';
        }
    }
}

void decrypt(char text[], int key)
{
    int i;

    for (i = 0; text[i] != '\0'; i++)
    {
        if (text[i] >= 'A' && text[i] <= 'Z')
        {
            text[i] = (text[i] - 'A' - key + 26) % 26 + 'A';
        }
        else if (text[i] >= 'a' && text[i] <= 'z')
        {
            text[i] = (text[i] - 'a' - key + 26) % 26 + 'a';
        }
    }
}

int main()
{
    char text[100];
    int key;

    printf("Enter the message: ");
    fgets(text, sizeof(text), stdin);

    printf("Enter the key: ");
    scanf("%d", &key);

    key = key % 26;

    printf("\nOriginal Message: %s", text);

    encrypt(text, key);

    printf("Encrypted Message: %s", text);

    decrypt(text, key);

    printf("Decrypted Message: %s", text);

    return 0;
}

#include <stdio.h>

int main()
{
    int bucket_size, output_rate;
    int n, incoming, stored = 0;
    int i;

    printf("Enter bucket size: ");
    scanf("%d", &bucket_size);

    printf("Enter output rate: ");
    scanf("%d", &output_rate);

    printf("Enter number of time units: ");
    scanf("%d", &n);

    for (i = 1; i <= n; i++)
    {
        printf("\nEnter number of packets arriving at time %d: ", i);
        scanf("%d", &incoming);

        printf("Packets arriving: %d\n", incoming);

        if (stored + incoming > bucket_size)
        {
            int dropped = (stored + incoming) - bucket_size;
            stored = bucket_size;

            printf("Packets dropped: %d\n", dropped);
        }
        else
        {
            stored = stored + incoming;
            printf("Packets dropped: 0\n");
        }

        if (stored >= output_rate)
        {
            stored = stored - output_rate;
            printf("Packets transmitted: %d\n", output_rate);
        }
        else
        {
            printf("Packets transmitted: %d\n", stored);
            stored = 0;
        }

        printf("Packets remaining in bucket: %d\n", stored);
    }

    // Empty remaining packets
    while (stored > 0)
    {
        if (stored >= output_rate)
        {
            stored = stored - output_rate;
            printf("\nPackets transmitted: %d", output_rate);
        }
        else
        {
            printf("\nPackets transmitted: %d", stored);
            stored = 0;
        }

        printf("\nPackets remaining: %d", stored);
    }

    return 0;
}
